#pragma once
#include "inventory_view.h"
#include "ui_transform.h"
#include "overlay_font.h"
#include <array>
#include <string>
namespace destinia {
enum class InventoryEvent {None,Close,Choose};
struct InventoryBox {int x,y,w,h;bool contains(int px,int py)const{return px>=x&&py>=y&&px<x+w&&py<y+h;}};
inline InventoryBox inventoryPanelRect(int w,int h){return{(w-360)/2,(h-214)/2,360,214};}
inline InventoryBox inventoryBadge(int w,int h){return{w/2+120,h/2-70,76,22};}
inline UiTransform inventoryTransform(int w,int h,int scale,bool open){auto p=inventoryPanelRect(w,h);return open?UiTransform{w,h,scale,UiAnchor::Center,p.w,p.h,p.x,p.y}:UiTransform{w,h,scale,UiAnchor::Center,392,240};}
inline InventoryBox inventoryControl(int id,int w,int h){auto p=inventoryPanelRect(w,h);if(id<4){int x[]={6,92,164,256},width[]={84,70,90,98};return{p.x+x[id],p.y+25,width[id],19};}if(id==4)return{p.x+6,p.y+47,158,19};if(id==5)return{p.x+168,p.y+47,78,19};return{p.x+250,p.y+47,104,19};}
inline int inventoryHit(int x,int y,int w,int h,int scale,bool open){auto point=inventoryTransform(w,h,scale,open).inverse(x,y);x=point.first;y=point.second;if(!open)return inventoryBadge(w,h).contains(x,y)?20:-1;auto p=inventoryPanelRect(w,h);for(int i=0;i<7;i++)if(inventoryControl(i,w,h).contains(x,y))return i;if(InventoryBox{p.x+302,p.y+3,54,19}.contains(x,y))return 11;for(int i=0;i<6;i++)if(InventoryBox{p.x+6,p.y+86+15*i,348,14}.contains(x,y))return 30+i;if(InventoryBox{p.x+6,p.y+189,50,19}.contains(x,y))return 8;if(InventoryBox{p.x+60,p.y+189,50,19}.contains(x,y))return 9;if(InventoryBox{p.x+116,p.y+189,238,19}.contains(x,y))return 10;return -1;}
struct InventoryPanel {
 std::vector<InventoryItem> items;std::vector<std::string> names;std::vector<size_t> view;InventoryQuery query;
 int selectedPool=-1,focus=0,levelChoice=0,priceChoice=0;size_t page=0;std::string error;
 std::optional<size_t> selected()const{return inventorySelection(items,view,selectedPool);}
 bool canChoose()const{auto at=selected();return at&&*at/6==page;}
 void rebuild(){view=inventoryView(items,query);auto at=selected();if(at)page=*at/6;else page=std::min(page,view.empty()?size_t(0):(view.size()-1)/6);error.clear();}
 void reset(){query={};levelChoice=priceChoice=0;rebuild();}
 void cycle(int control,int direction,int heroLevel){auto next=[&](int value,int count){return(value+direction+count)%count;};
  if(control==0)query.type=next(query.type+1,9)-1;
  else if(control==1)query.rank=next(query.rank+1,6)-1;
  else if(control==2){levelChoice=next(levelChoice,12);query.minLevel=levelChoice<2?0:(levelChoice-2)*10+1;query.maxLevel=levelChoice==0?65535:levelChoice==1?heroLevel:(levelChoice-1)*10;}
  else if(control==3){priceChoice=next(priceChoice,6);int lo[]={0,0,101,501,1001,5001},hi[]={2147483647,100,500,1000,5000,2147483647};query.minPrice=lo[priceChoice];query.maxPrice=hi[priceChoice];}
  else if(control==4)query.sort=InventorySort(next(int(query.sort),5));else if(control==5)query.descending=!query.descending;else if(control==6){reset();return;}rebuild();
 }
 void move(int delta){if(view.empty())return;auto at=selected();long long position=at&&*at/6==page?static_cast<long long>(*at)+delta:static_cast<long long>(std::min(view.size()-1,page*6+(delta<0?5:0)));position=std::clamp(position,0ll,static_cast<long long>(view.size()-1));selectedPool=items[view[size_t(position)]].pool;page=size_t(position)/6;}
 InventoryEvent key(int key,int heroLevel){if(key==10||key==27)return InventoryEvent::Close;if(focus<7){if(key==3)focus=std::max(0,focus-1);else if(key==9){focus++;if(focus==7&&!selected())move(1);}else if(key==5)cycle(focus,-1,heroLevel);else if(key==7||key==17||key==6)cycle(focus,1,heroLevel);}else{if(key==3){auto at=selected();if(at&&*at==0)focus=6;else move(-1);}else if(key==9)move(1);else if(key==5)move(-6);else if(key==7)move(6);else if((key==17||key==6)&&canChoose())return InventoryEvent::Choose;}return InventoryEvent::None;}
 InventoryEvent hit(int hit,int heroLevel){if(hit>=0&&hit<7){focus=hit;cycle(hit,1,heroLevel);}else if(hit>=30&&hit<36){size_t row=page*6+hit-30;if(row<view.size()){selectedPool=items[view[row]].pool;focus=7;}}else if(hit==8||hit==9){if(!view.empty()){page=hit==8?(page?page-1:0):std::min(page+1,(view.size()-1)/6);}}else if(hit==10&&canChoose())return InventoryEvent::Choose;else if(hit==11)return InventoryEvent::Close;return InventoryEvent::None;}
 std::string label(int id)const{const char* types[]={"TODOS","ESPADA","ARMA","ADAGA","ELMO","ARMADURA","LUVAS","BOTAS","ACESS."};const char* sorts[]={"ORIGINAL","TIPO","RANK","NIVEL","PRECO"};if(id==0)return types[query.type+1];if(id==1)return query.rank<0?"R:TODOS":"R:"+std::to_string(query.rank);if(id==2)return levelChoice==0?"LV:TODOS":levelChoice==1?"LV:USAVEL":"LV:"+std::to_string(query.minLevel)+"-"+std::to_string(query.maxLevel);if(id==3)return priceChoice==0?"G:TODOS":"G:"+std::to_string(query.minPrice)+(priceChoice==5?"+":"-"+std::to_string(query.maxPrice));if(id==4)return std::string("ORDEM:")+sorts[int(query.sort)];if(id==5)return query.descending?"DECRESC.":"CRESC.";return"LIMPAR";}
};
inline void paintInventory(uint8_t* pixels,int w,int h,int scale,const InventoryPanel& panel,bool open,bool visible){if(!open&&!visible)return;auto transform=inventoryTransform(w,h,scale,open);auto rect=[&](int x,int y,int rw,int rh,uint16_t c){auto r=transform.rect(x,y,rw,rh);for(int yy=std::max(0,r.y);yy<std::min(h,r.y+r.h);yy++)for(int xx=std::max(0,r.x);xx<std::min(w,r.x+r.w);xx++){auto at=(yy*w+xx)*2;pixels[at]=c&255;pixels[at+1]=c>>8;}};auto text=[&](int x,int y,const std::string& value,uint16_t c,int limit=60){auto origin=transform.point(x,y);int count=0;limit=std::max(0,int(limit*transform.scale()));for(size_t at=0;at<value.size()&&count++<limit;origin.first+=6){auto glyph=overlayGlyph(overlayCodepoint(value,at));for(int i=0;i<5;i++)for(int j=0;j<11;j++)if(glyph[i]&(1<<j)){int xx=origin.first+i,yy=origin.second+j-2;if(xx>=0&&xx<w&&yy>=0&&yy<h){auto n=(yy*w+xx)*2;pixels[n]=c&255;pixels[n+1]=c>>8;}}}};const uint16_t dark=0x1946,gold=0xe5b2,white=0xe71c,border=0x6b6b;auto button=[&](InventoryBox r,const std::string& label,bool active){rect(r.x,r.y,r.w,r.h,active?gold:border);rect(r.x+1,r.y+1,r.w-2,r.h-2,dark);text(r.x+3,r.y+7,label,active?gold:white,(r.w-6)/6);};if(!open){button(inventoryBadge(w,h),"FILTROS",false);return;}for(int i=0;i<w*h;i++){pixels[2*i]=0x41;pixels[2*i+1]=0x08;}auto p=inventoryPanelRect(w,h);rect(p.x,p.y,p.w,p.h,border);rect(p.x+2,p.y+2,p.w-4,p.h-4,dark);text(p.x+8,p.y+9,"EQUIPAMENTOS - FILTROS",gold);button({p.x+302,p.y+3,54,19},"VOLTAR",false);for(int i=0;i<7;i++)button(inventoryControl(i,w,h),panel.label(i),panel.focus==i);text(p.x+8,p.y+76,"B/P",white);text(p.x+44,p.y+76,"ITEM",white);text(p.x+224,p.y+76,"R",white);text(p.x+242,p.y+76,"LV",white);text(p.x+278,p.y+76,"GOLD",white);const uint16_t ranks[]={white,0x07e0,0x5dff,0xd01f,0xffe0};for(size_t row=0;row<6;row++){size_t at=panel.page*6+row;if(at>=panel.view.size())break;size_t index=panel.view[at];const auto& item=panel.items[index];int y=p.y+86+15*int(row);if(item.pool==panel.selectedPool)rect(p.x+6,y,348,14,0x3269);text(p.x+8,y+5,std::to_string(item.bag+1)+":"+std::to_string(item.slot+1),white);text(p.x+44,y+5,index<panel.names.size()?panel.names[index]:"EQUIPAMENTO",ranks[item.rank],26);text(p.x+224,y+5,std::to_string(item.rank),ranks[item.rank]);text(p.x+242,y+5,std::to_string(item.level),white);text(p.x+278,y+5,std::to_string(item.price),gold,12);}if(panel.view.empty())text(p.x+20,p.y+110,"NENHUM EQUIPAMENTO NESTE FILTRO",white);text(p.x+8,p.y+179,panel.error.empty()?"PAG "+std::to_string(panel.page+1)+"  ITENS "+std::to_string(panel.view.size())+" - CONFIRME NO MENU ORIGINAL":panel.error,gold,56);button({p.x+6,p.y+189,50,19},"ANT.",false);button({p.x+60,p.y+189,50,19},"PROX.",false);button({p.x+116,p.y+189,238,19},"VOLTAR AO ITEM SELECIONADO",panel.focus==7&&panel.canChoose());}
}
